target.css:
:root {
  --ink: #17212b;
  --muted: #64717b;
  --paper: #fffdf7;
  --line: #d8d9d2;
  --soft: #f1f2ec;
  --red: #e4584d;
  --red-pale: #fff0ed;
  --blue: #377fd1;
  --blue-pale: #eaf3ff;
  --lime: #62a76b;
  --dark: #1d2933;
}

* {
  box-sizing: border-box;
}

.panel {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.topbar {
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}

.event-mark {
  display: flex;
  align-items: center;
  gap: 9px;
}

.mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 8px;
  background: var(--ink);
  color: var(--paper);
  font-size: 19px;
}

.event-mark strong,
.event-mark small {
  display: block;
}

.event-mark strong {
  font-size: 13px;
  letter-spacing: .08em;
}

.event-mark small,
.round,
.bot small,
.arena-label,
.ring-edge,
.telemetry h2,
.stats span,
.signal,
.controls {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .09em;
}

.event-mark small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 8px;
}

.round {
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 5px;
  color: var(--muted);
}

.match-area {
  display: grid;
  grid-template-columns: 1.45fr .85fr;
  gap: 12px;
  padding: 12px 14px;
}

.arena {
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 10px;
}

.arena-label,
.ring-edge {
  display: flex;
  justify-content: space-between;
  padding: 7px 9px;
  background: var(--soft);
}

.arena-label {
  border-bottom: 1px solid var(--line);
}

.arena-label b {
  color: var(--red);
}

.fighters {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 11px 8px;
}

.bot {
  width: 104px;
  min-height: 70px;
  padding: 9px 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.bot.red {
  background: var(--red-pale);
  border-color: var(--red);
}

.bot.blue {
  background: var(--blue-pale);
  border-color: var(--blue);
  text-align: right;
}

.bot-id,
.bot strong,
.bot small {
  display: block;
}

.bot-id {
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.bot strong {
  font-size: 12px;
  letter-spacing: .02em;
}

.bot small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 7px;
}

.versus {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.ring-edge {
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 8px;
}

.telemetry {
  padding: 10px;
  border-radius: 10px;
  background: var(--dark);
  color: var(--paper);
}

.telemetry h2 {
  margin: 0 0 8px;
  color: var(--lime);
  font-size: 9px;
}

.stats {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.stats li {
  display: flex;
  justify-content: space-between;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--muted);
}

.stats span {
  color: var(--line);
  font-size: 8px;
}

.stats b {
  font-size: 11px;
}

.signal {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 9px 0 0;
  color: var(--lime);
  font-size: 8px;
}

.signal i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lime);
}

.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 8px;
}

.controls b {
  color: var(--lime);
}

.actions {
  display: flex;
  gap: 6px;
}

button {
  padding: 7px 9px;
  border: 1px solid var(--ink);
  border-radius: 5px;
  background: var(--paper);
  color: var(--ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
}

button.primary {
  background: var(--ink);
  color: var(--paper);
}

